diff --git a/wine/dlls/mfplat/colorconvert.c b/wine/dlls/mfplat/colorconvert.c
new file mode 100644
index 0000000..92322e8
--- /dev/null
+++ b/wine/dlls/mfplat/colorconvert.c
@@ -0,0 +1,901 @@
+/* GStreamer Color Converter
+ *
+ * Copyright 2020 Derek Lesho
