diff --git a/wine/dlls/windows.gaming.input/ramp_effect.c b/wine/dlls/windows.gaming.input/ramp_effect.c
new file mode 100644
index 0000000..fadcf15
--- /dev/null
+++ b/wine/dlls/windows.gaming.input/ramp_effect.c
@@ -0,0 +1,278 @@
+/* WinRT Windows.Gaming.Input implementation
+ *
+ * Copyright 2022 Rémi Bernon for CodeWeavers
+ *
